sys_variable_value.value:
(function execute(inputs, outputs) {
    // Keeps only one open defect per integration process (identified by Correlation ID).
    // Open = active defect (closed states of rm_defect: 3 Closed Complete, 7 Cancelled).
    var corr = inputs.correlation_id;

    // Same values as the record producer "Raise a Defect", kept in system properties
    var GROUP = gs.getProperty('x_snc_spm_xero_i_0.defect_assignment_group', '');
    var COMPANY = gs.getProperty('x_snc_spm_xero_i_0.defect_company', '');
    var SERVICE_ACCOUNT = gs.getProperty('x_snc_spm_xero_i_0.service_account', '');

    function openDefects() {
        var gr = new GlideRecord('rm_defect');
        gr.addQuery('correlation_id', corr);
        gr.addActiveQuery();
        gr.orderBy('sys_created_on');
        gr.query();
        return gr;
    }

    // 1. A defect is already open: add the failure as a work note
    var open = openDefects();
    if (open.next()) {
        open.work_notes = inputs.details;
        open.update();
        return;
    }

    // 2. None open: create one with the same structure as the record producer
    var def = new GlideRecord('rm_defect');
    def.initialize();
    def.short_description = inputs.short_description;
    def.description = [
        '====================================================',
        'Raised via SPM Xero Integration',
        '====================================================',
        '',
        'Environment:',
        '-----------',
        'Production',
        '',
        'Steps to Reproduce:',
        '-----------',
        '',
        '',
        'Expected Result:',
        '-----------',
        '',
        '',
        'Actual Result:',
        '-----------',
        inputs.details || '',
        '',
        'Business Impact:',
        '-----------',
        '',
        '',
        'Additional Information:',
        '-----------',
        ''
    ].join('\n');
    def.correlation_id = corr;
    def.priority = 3;
    if (GROUP) {
        def.assignment_group = GROUP;
    } else {
        gs.error('[Xero] Property x_snc_spm_xero_i_0.defect_assignment_group is empty; defect created without assignment group.');
    }
    if (COMPANY) {
        def.company = COMPANY;
    } else {
        gs.error('[Xero] Property x_snc_spm_xero_i_0.defect_company is empty; defect created with the default company.');
    }
    var usr = new GlideRecord('sys_user');
    if (SERVICE_ACCOUNT && usr.get('user_name', SERVICE_ACCOUNT)) {
        def.opened_by = usr.getUniqueValue();
    } else {
        gs.error('[Xero] Service account "' + SERVICE_ACCOUNT + '" not found; defect created with the default Opened by.');
    }
    var newId = def.insert();

    // 3. Two failures at the same time may create two defects:
    //    keep the oldest, add the failure to it and cancel the new one as duplicate
    var all = openDefects();
    if (all.next() && all.getUniqueValue() != newId) {
        all.work_notes = inputs.details;
        all.update();
        var dup = new GlideRecord('rm_defect');
        if (dup.get(newId)) {
            dup.state = 7; // Cancelled
            dup.work_notes = 'Duplicate of ' + all.getValue('number') + ' (created at the same time).';
            dup.update();
        }
    }
})(inputs, outputs);

